"use strict";(globalThis.webpackChunkweb=globalThis.webpackChunkweb||[]).push([[9994],{4163(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/mmp/docs/intro","label":"The Mystical Metaphysical Number System","docId":"intro","unlisted":false},{"type":"category","label":"Number","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/mmp/docs/Number/LengthAndPrecision","label":"Length & Precision","docId":"Number/LengthAndPrecision","unlisted":false},{"type":"link","href":"/mmp/docs/Number/Physical","label":"Physical Numbers","docId":"Number/Physical","unlisted":false},{"type":"link","href":"/mmp/docs/Number/Metaphysical","label":"Metaphysical Numbers","docId":"Number/Metaphysical","unlisted":false},{"type":"link","href":"/mmp/docs/Number/Physicalization","label":"Physicalization & Metaphysicalization","docId":"Number/Physicalization","unlisted":false},{"type":"link","href":"/mmp/docs/Number/Mystical","label":"Mystical Numbers","docId":"Number/Mystical","unlisted":false},{"type":"category","label":"The Resolution","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/mmp/docs/Number/Resolution/InfiniteNothingness","label":"The Infinite Nothingness","docId":"Number/Resolution/InfiniteNothingness","unlisted":false},{"type":"link","href":"/mmp/docs/Number/Resolution/HolographicUnity","label":"Holographic Unity","docId":"Number/Resolution/HolographicUnity","unlisted":false},{"type":"link","href":"/mmp/docs/Number/Resolution/OuroborosOperator","label":"The Ouroboros Operator","docId":"Number/Resolution/OuroborosOperator","unlisted":false}],"href":"/mmp/docs/Number/Resolution/"},{"type":"link","href":"/mmp/docs/Number/SmokingGunZeroPowersOfZero","label":"The Smoking Gun: Zero Powers of Zero","docId":"Number/SmokingGunZeroPowersOfZero","unlisted":false},{"type":"link","href":"/mmp/docs/Number/BoxMath","label":"Box Math","docId":"Number/BoxMath","unlisted":false}],"href":"/mmp/docs/Number/"},{"type":"category","label":"Applications","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/mmp/docs/Applications/Bridging","label":"Bridging","docId":"Applications/Bridging","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/PrecisionVsExactness","label":"Precision vs Exactness","docId":"Applications/PrecisionVsExactness","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/HarmonicProportions","label":"Harmonic Proportions","docId":"Applications/HarmonicProportions","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/Music","label":"Music","docId":"Applications/Music","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/SmartContracts","label":"Smart Contracts","docId":"Applications/SmartContracts","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/OntologicalCompleteness","label":"Ontological Completeness","docId":"Applications/OntologicalCompleteness","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/Memristors","label":"Memristors","docId":"Applications/Memristors","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/BalancedTernary","label":"Balanced Ternary","docId":"Applications/BalancedTernary","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/BellsInequality","label":"Bell\'s Inequality","docId":"Applications/BellsInequality","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/KnotTheory","label":"Knot Theory","docId":"Applications/KnotTheory","unlisted":false},{"type":"link","href":"/mmp/docs/Applications/QCDRegularization","label":"QCD Regularization & Oriented Poles","docId":"Applications/QCDRegularization","unlisted":false}],"href":"/mmp/docs/Applications/"},{"type":"category","label":"ArchaeoArithmetic [Coming Soon]","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/EgyptianMaths","label":"Egyptian Maths","docId":"ArchaeoArithmetic/EgyptianMaths","unlisted":false},{"type":"category","label":"Mathematical Coincidences","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/MathematicalCoincidences/PiThroughPhi","label":"\u03c0 through \u03c6","docId":"ArchaeoArithmetic/MathematicalCoincidences/PiThroughPhi","unlisted":false},{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/MathematicalCoincidences/VolumeCorrelation","label":"Volume Correlation","docId":"ArchaeoArithmetic/MathematicalCoincidences/VolumeCorrelation","unlisted":false}],"href":"/mmp/docs/ArchaeoArithmetic/MathematicalCoincidences/"},{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/TheCubit","label":"The Cubit","docId":"ArchaeoArithmetic/TheCubit","unlisted":false},{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/GreatPyramid","label":"The Great Pyramid","docId":"ArchaeoArithmetic/GreatPyramid","unlisted":false},{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/BoxMathPrimes","label":"Box Math & Primes to 11","docId":"ArchaeoArithmetic/BoxMathPrimes","unlisted":false},{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/Fibonacci","label":"Golden Ratio Power Series Approximation","docId":"ArchaeoArithmetic/Fibonacci","unlisted":false},{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/PrecessionGreatYear","label":"Precession & the Great Year","docId":"ArchaeoArithmetic/PrecessionGreatYear","unlisted":false},{"type":"link","href":"/mmp/docs/ArchaeoArithmetic/MagnitudeAgitation","label":"MagnitudeAgitation","docId":"ArchaeoArithmetic/MagnitudeAgitation","unlisted":false}],"href":"/mmp/docs/ArchaeoArithmetic/"},{"type":"category","label":"BoxMath","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/mmp/docs/BoxMath/BoxMathSDK","label":"BoxMath SDK Introduction","docId":"BoxMath/BoxMathSDK","unlisted":false},{"type":"category","label":"Encoding Familiar Mathematics","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/mmp/docs/BoxMath/Encoding/NaturalNumbers","label":"1. Zero, the Box, and the Natural Numbers","docId":"BoxMath/Encoding/NaturalNumbers","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/PolynumberTerm","label":"1. Polynumbers","docId":"BoxMath/Encoding/PolynumberTerm","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/Incommensurability","label":"2. Incommensurability \u2014 \u221a2 and Integer Powers","docId":"BoxMath/Encoding/Incommensurability","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/Multivariate","label":"4. Multivariate: Base Multinumbers","docId":"BoxMath/Encoding/Multivariate","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/Logic","label":"5. From Encoding to Logic","docId":"BoxMath/Encoding/Logic","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/Transfer","label":"6. A Transfer with a Tax Rate","docId":"BoxMath/Encoding/Transfer","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/ConstantProduct","label":"7. Constant Product Invariant","docId":"BoxMath/Encoding/ConstantProduct","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/Truncation","label":"8. Degree Truncation and Composability","docId":"BoxMath/Encoding/Truncation","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/BalancerHack","label":"9. Case Study: The Balancer V2 Hack","docId":"BoxMath/Encoding/BalancerHack","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/LinearAlgebra","label":"10. Linear Algebra Primitives: Pixels, Vexels, Maxels","docId":"BoxMath/Encoding/LinearAlgebra","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/Encoding/PixelRouter","label":"11. Case Study: Pixel-Algebraic Route Validation","docId":"BoxMath/Encoding/PixelRouter","unlisted":false}],"href":"/mmp/docs/category/encoding-familiar-mathematics"},{"type":"category","label":"API Reference","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/mmp/docs/BoxMath/API/Typescript","label":"TypeScript API","docId":"BoxMath/API/Typescript","unlisted":false},{"type":"link","href":"/mmp/docs/BoxMath/API/Solidity","label":"Solidity API","docId":"BoxMath/API/Solidity","unlisted":false}],"href":"/mmp/docs/BoxMath/API/"}]}]},"docs":{"Applications/Applications":{"id":"Applications/Applications","title":"Applications","description":"This section lays out the why of rerouting box math \u2014 the practical and philosophical payoffs of founding arithmetic on the infinite nothingness rather than the empty box.","sidebar":"tutorialSidebar"},"Applications/BalancedTernary":{"id":"Applications/BalancedTernary","title":"Balanced Ternary","description":"The Soviet Setun computer (1958, Nikolay Brusentsov) operated in balanced ternary with digits $\\\\{-1, 0, +1\\\\}$ (written $\\\\{\\\\bar, 0, 1\\\\}$). Brusentsov showed it is the most efficient radix for information encoding \u2014 it minimizes the product of radix and number of digits needed for a given range.","sidebar":"tutorialSidebar"},"Applications/BellsInequality":{"id":"Applications/BellsInequality","title":"Bell\'s Inequality","description":"Bell\'s theorem shows that no local hidden variable theory can reproduce quantum correlations. The inequality","sidebar":"tutorialSidebar"},"Applications/Bridging":{"id":"Applications/Bridging","title":"Bridging","description":"Two tribes have been arguing past each other for a century.","sidebar":"tutorialSidebar"},"Applications/HarmonicProportions":{"id":"Applications/HarmonicProportions","title":"Harmonic Proportions","description":"Harmonic proportions \u2014 ratios of small integers \u2014 are the natural language of acoustics, tuning, and resonance. They are also where the mismatch between the real number system and physical reality shows up most clearly.","sidebar":"tutorialSidebar"},"Applications/KnotTheory":{"id":"Applications/KnotTheory","title":"Knot Theory","description":"Tait\'s Knots","sidebar":"tutorialSidebar"},"Applications/Memristors":{"id":"Applications/Memristors","title":"Memristors","description":"A memristor (memory resistor) is a two-terminal circuit element whose resistance depends on the history of current that has passed through it. It was theorized by Leon Chua in 1971 and first physically realized by HP Labs in 2008. Unlike a resistor (which has fixed resistance), a memristor retains a state \u2014 it remembers how much charge has flowed, and its resistance reflects that history.","sidebar":"tutorialSidebar"},"Applications/Music":{"id":"Applications/Music","title":"Music","description":"Overtones and the Harmonic Series","sidebar":"tutorialSidebar"},"Applications/OntologicalCompleteness":{"id":"Applications/OntologicalCompleteness","title":"Ontological Completeness","description":"Standard mathematics, and much of Western philosophy following it, treats zero as absence. The empty set is nothing. The zero vector is the origin. Null is the lack of a value. This is so deeply embedded in the notation that it rarely surfaces as an assumption \u2014 it simply is the way things are.","sidebar":"tutorialSidebar"},"Applications/PrecisionVsExactness":{"id":"Applications/PrecisionVsExactness","title":"Precision vs Exactness","description":"These two words are often used interchangeably. MMP distinguishes them sharply.","sidebar":"tutorialSidebar"},"Applications/QCDRegularization":{"id":"Applications/QCDRegularization","title":"QCD Regularization & Oriented Poles","description":"Quantum chromodynamics \u2014 the theory of the strong force \u2014 is arguably the most precisely tested physical theory we have. Yet at its computational core sits a procedure that standard mathematics cannot fully justify: regularization, the controlled navigation of divergences at the boundary of the number system.","sidebar":"tutorialSidebar"},"Applications/SmartContracts":{"id":"Applications/SmartContracts","title":"Smart Contracts","description":"Blockchains are deterministic \u2014 every node must compute the same result. This rules out floating-point arithmetic entirely: floating-point results can differ between hardware implementations, compiler versions, and rounding modes. Smart contracts on Ethereum and similar platforms work exclusively in integers, typically representing value in the smallest unit (wei, satoshi) and requiring all division to be integer division.","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/ArchaeoArithmetic":{"id":"ArchaeoArithmetic/ArchaeoArithmetic","title":"ArchaeoArithmetic [Coming Soon]","description":"MMP is motivated by the persuasion that the constructors of the Great Pyramid had a more nuanced understanding of how nature absolves itself of incommensurability \u2014 nature does not use \u03c0 (Buckminster Fuller) \u2014 and that this understanding was encoded in the pyramid.","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/BoxMathPrimes":{"id":"ArchaeoArithmetic/BoxMathPrimes","title":"Box Math & Primes to 11","description":"As an application we consider the finite proportions of the great pyramid and contextify them within the frame work of the box arithmetic.","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/EgyptianMaths":{"id":"ArchaeoArithmetic/EgyptianMaths","title":"Egyptian Maths","description":"TODO: ancient Egyptian number systems, astronomical science, and what the priests understood","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/Fibonacci":{"id":"ArchaeoArithmetic/Fibonacci","title":"Golden Ratio Power Series Approximation","description":"Using the FIA framework with the same prime box construction, we approximate the golden ratio power series instead of the sum-of-divisors function.","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/GreatPyramid":{"id":"ArchaeoArithmetic/GreatPyramid","title":"The Great Pyramid","description":"TODO: how the pyramid encodes a more nuanced understanding of incommensurability; MMP as the lens to read it","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/MagnitudeAgitation":{"id":"ArchaeoArithmetic/MagnitudeAgitation","title":"MagnitudeAgitation","description":"The Agitation of the Anciengt Egyptian conception of magnitudes","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/MathematicalCoincidences/MathematicalCoincidences":{"id":"ArchaeoArithmetic/MathematicalCoincidences/MathematicalCoincidences","title":"Mathematical Coincidences","description":"\u03c0, \u03c6, and powers of 2 \u2014 the curious relationships between these constants and how they structure ancient measure.","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/MathematicalCoincidences/PiThroughPhi":{"id":"ArchaeoArithmetic/MathematicalCoincidences/PiThroughPhi","title":"\u03c0 through \u03c6","description":"TODO: the relationship between \u03c0 and \u03c6 and powers of 2","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/MathematicalCoincidences/VolumeCorrelation":{"id":"ArchaeoArithmetic/MathematicalCoincidences/VolumeCorrelation","title":"Volume Correlation","description":"The topic explores another golden ratio based mathematical coincidence.  Namely that radius of a unit sphere happens to be close to $1/\\\\phi$","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/PrecessionGreatYear":{"id":"ArchaeoArithmetic/PrecessionGreatYear","title":"Precession & the Great Year","description":"TODO: precession, the full year, and what the priests revealed vs concealed","sidebar":"tutorialSidebar"},"ArchaeoArithmetic/TheCubit":{"id":"ArchaeoArithmetic/TheCubit","title":"The Cubit","description":"TODO: \u03c0 with \u03c6 with powers of 2 \u2014 the cubit as the bridge between these constants and ancient measure","sidebar":"tutorialSidebar"},"BoxMath/API/API":{"id":"BoxMath/API/API","title":"API Reference","description":"The BoxMath SDK ships two isomorphic implementations of the same primitives:","sidebar":"tutorialSidebar"},"BoxMath/API/Solidity":{"id":"BoxMath/API/Solidity","title":"Solidity API","description":"Two contracts ship in hardhat/contracts/:","sidebar":"tutorialSidebar"},"BoxMath/API/Typescript":{"id":"BoxMath/API/Typescript","title":"TypeScript API","description":"Import from the boxmath package:","sidebar":"tutorialSidebar"},"BoxMath/BoxMathSDK":{"id":"BoxMath/BoxMathSDK","title":"BoxMath SDK Introduction","description":"New to polynumbers? Start with Encoding Familiar Mathematics \u2014 it derives the mapping from standard polynomials to the box arithmetic encoding before introducing the API.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/BalancerHack":{"id":"BoxMath/Encoding/BalancerHack","title":"9. Case Study: The Balancer V2 Hack","description":"On November 3 2025, an attacker drained $128.64 million from Balancer V2\'s ComposableStablePool contracts across six networks in under 30 minutes. The root cause was a rounding error in the pool\'s upscaling function \u2014 not a logic bug, not a reentrancy, not a missing access check. The arithmetic itself was used as a weapon.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/ConstantProduct":{"id":"BoxMath/Encoding/ConstantProduct","title":"7. Constant Product Invariant","description":"The AMM constant product curve is the multiplicative analogue of the linear conservation law from \xa76:","sidebar":"tutorialSidebar"},"BoxMath/Encoding/Incommensurability":{"id":"BoxMath/Encoding/Incommensurability","title":"2. Incommensurability \u2014 \u221a2 and Integer Powers","description":"Box arithmetic has no fractions, so quantities like \u221a2 \u2014 numbers whose square is a natural number but which are not themselves natural numbers \u2014 require a different treatment than you might expect.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/LinearAlgebra":{"id":"BoxMath/Encoding/LinearAlgebra","title":"10. Linear Algebra Primitives: Pixels, Vexels, Maxels","description":"The polynumber layer of box arithmetic \u2014 Polynumber, Multinumber, degree truncation \u2014 gives us a powerful tool for encoding scalar invariants. But DeFi protocols do not operate on scalars alone. A portfolio is a vector of balances. A swap is a linear map between token spaces. A routing graph is a directed structure over token indices. These are linear-algebraic objects, and box arithmetic has a natural foundation for them that requires no fractions, no floating point, and no division.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/Logic":{"id":"BoxMath/Encoding/Logic","title":"5. From Encoding to Logic","description":"The previous pages showed how to encode a polynomial as a box. Now we use those boxes to make assertions \u2014 to check that a condition holds rather than just compute a value.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/Multivariate":{"id":"BoxMath/Encoding/Multivariate","title":"4. Multivariate: Base Multinumbers","description":"To go beyond one variable, Wildberger introduces base multinumbers \u2014 a family of primitive elements, one for each natural number index:","sidebar":"tutorialSidebar"},"BoxMath/Encoding/NaturalNumbers":{"id":"BoxMath/Encoding/NaturalNumbers","title":"1. Zero, the Box, and the Natural Numbers","description":"Box arithmetic starts at the bottom \u2014 not with variables or polynomials, but with the simplest thing that exists: nothing.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/PixelRouter":{"id":"BoxMath/Encoding/PixelRouter","title":"11. Case Study: Pixel-Algebraic Route Validation","description":"Multi-hop swaps are one of the most common operations in DeFi. Routing USDC \u2192 BTC through an intermediate ETH pool requires the router to verify that the output token of each hop equals the input token of the next \u2014 a path connectivity check.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/PolynumberTerm":{"id":"BoxMath/Encoding/PolynumberTerm","title":"1. Polynumbers","description":"Box arithmetic begins with the natural numbers \u2014 zero and the counting numbers. No negatives, no fractions, no irrationals. Everything built from here stays in that world.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/Transfer":{"id":"BoxMath/Encoding/Transfer","title":"6. A Transfer with a Tax Rate","description":"A linear conservation law: three parties hold balances, and the total must be preserved across every transaction.","sidebar":"tutorialSidebar"},"BoxMath/Encoding/Truncation":{"id":"BoxMath/Encoding/Truncation","title":"8. Degree Truncation and Composability","description":"SafeMath, PRBMath, and Q-number libraries each solve a real problem. SafeMath prevents integer overflow. PRBMath provides high-precision fixed-point arithmetic within a single protocol. Q-numbers give you a consistent decimal convention. None of them address what happens at the boundary between protocols \u2014 and that boundary is where the most damaging exploits live.","sidebar":"tutorialSidebar"},"intro":{"id":"intro","title":"The Mystical Metaphysical Number System","description":"As analysis dispensed the geometers, and the Renaissance minds laid content on the limits described by Galois on polynomials, the notion of the axioms \u2014 the linchpins of mathematics \u2014 departed from the physical sensibilities of the compass and square, and were watered down to paper over incommensurate nuances. Perhaps the departure would\'ve remained permanent, if those hadn\'t found the transistor so conducive to boolean logic. But alas, rounding errors are exploited for major sums of money, a good deal of music is needlessly out of tune, and grand mathematical traditions, such as the quadrature of the circle, are dispensed as \'solved\' to great calamity for a lack of appreciation of the distinction between precision at iteration and exactness.","sidebar":"tutorialSidebar"},"Number/BoxMath":{"id":"Number/BoxMath","title":"Box Math","description":"Wildberger\'s Box Arithmetic","sidebar":"tutorialSidebar"},"Number/LengthAndPrecision":{"id":"Number/LengthAndPrecision","title":"Length & Precision","description":"Every number has two fundamental properties:","sidebar":"tutorialSidebar"},"Number/Metaphysical":{"id":"Number/Metaphysical","title":"Metaphysical Numbers","description":"A metaphysical number is one whose displacement never closes. Every digit placed narrows the interval but the interval never reaches zero width. No finite length perfectly describes the number \u2014 it can only be approached.","sidebar":"tutorialSidebar"},"Number/Mystical":{"id":"Number/Mystical","title":"Mystical Numbers","description":"By analyzing number through the lens of precision at iteration, MMP exposes the true character of zero and infinity. They are not simply the edges of the numberline \u2014 they reveal themselves as a pair, defined by a perfect inversion of magnitude and precision.","sidebar":"tutorialSidebar"},"Number/Number":{"id":"Number/Number","title":"Number","description":"The introduction established the philosophical motivation \u2014 the tension between nothingness and the infinite, the stress energy behind $0^0 = 1$, the quaternary balance that bequeaths the continuum. This section develops the formal machinery to make those ideas precise.","sidebar":"tutorialSidebar"},"Number/Physical":{"id":"Number/Physical","title":"Physical Numbers","description":"A physical number is one whose displacement on the numberline closes to zero in a finite number of iterations. Each digit placed reduces the uncertainty in its position; eventually the uncertainty is gone and the number is perfectly described. It is exactly where it is.","sidebar":"tutorialSidebar"},"Number/Physicalization":{"id":"Number/Physicalization","title":"Physicalization & Metaphysicalization","description":"Whether a number is physical or metaphysical is not always intrinsic \u2014 it can depend on the base system used to describe it. A number that demands infinite length in one base may terminate cleanly in another. Physicalization is the process of choosing (or moving to) a base in which a number becomes physical. Metaphysicalization is the reverse \u2014 a number that was physical loses its finite terminus.","sidebar":"tutorialSidebar"},"Number/Resolution/HolographicUnity":{"id":"Number/Resolution/HolographicUnity","title":"Holographic Unity","description":"The Ouroboros Operator","sidebar":"tutorialSidebar"},"Number/Resolution/InfiniteNothingness":{"id":"Number/Resolution/InfiniteNothingness","title":"The Infinite Nothingness","description":"The Mystical Numbers section established that zero and infinity are complements \u2014 perfectly inverted in length and precision. A new operation is required to hold them in tension. The infinite nothingness is that tension made explicit: the result of applying the ouroboros operator ($\\\\circlearrowright$) across the boundary.","sidebar":"tutorialSidebar"},"Number/Resolution/OuroborosOperator":{"id":"Number/Resolution/OuroborosOperator","title":"The Ouroboros Operator","description":"Two snakes, not one","sidebar":"tutorialSidebar"},"Number/Resolution/Resolution":{"id":"Number/Resolution/Resolution","title":"The Resolution","description":"The paradox at zero and infinity resolves into oriented voids, the ouroboros operator, and a trinary structure. Cross-composition produces unity; self-composition preserves superposition.","sidebar":"tutorialSidebar"},"Number/SmokingGunZeroPowersOfZero":{"id":"Number/SmokingGunZeroPowersOfZero","title":"The Smoking Gun: Zero Powers of Zero","description":"In MMP, subscript denotes orientation. The double composition that recovers unity is not a separate axiom \u2014 it is the identity","sidebar":"tutorialSidebar"}}}}')}}]);